export const LANGUAGE_CODES = Object.keys(LANGUAGES);

export const languageOf = code => LANGUAGES[code] ?? LANGUAGES.te;

export function fill(text, values) {
  return String(text).replace(/\{(\w+)\}/g, (_, key) => values[key] ?? '{' + key + '}');
}
